function formatIndianCurrency(num) {
  if (!num || isNaN(num)) return 'â‚¹ 0';
  if (num >= 10000000) {
    return `â‚¹ ${(num / 10000000).toFixed(2).replace(/\.00$/, '')} Cr`;
  }
  if (num >= 100000) {
    return `â‚¹ ${(num / 100000).toFixed(2).replace(/\.00$/, '')} Lac`;
  }
  return `â‚¹ ${Math.round(num).toLocaleString('en-IN')}`;
}

